type Role='WORKER'|'EMPLOYER'|'AGENCY';
type User={id:string;publicId:string;displayName:string;email:string;role:Role};
type Kind='job'|'worker'|'company';
type Item={id:string;kind:Kind;name:string;title:string;city:string;country:string;lat:number;lng:number;meta:string;verified?:boolean;salary?:string};

type Job={id:string;ownerId:string;company:string;title:string;city:string;country:string;salary?:string;description?:string;status:'PUBLISHED'|'CLOSED';createdAt:string;occupation?:string;employmentModel?:string;internationalApplicants?:boolean;legalRuleIds?:string[];name?:string;meta?:string};
type Application={id:string;jobId:string;jobTitle:string;company:string;workerId:string;workerName:string;employerId:string;status:string;createdAt:string;workerNationality?:string;complianceStatus?:ComplianceStatus;complianceUpdatedAt?:string};
type ComplianceStatus='NOT_STARTED'|'IN_PROGRESS'|'READY'|'NEEDS_REVIEW'|'EXPIRED';
type ComplianceCheck={id:string;rule:LegalRule;status:'READY'|'MISSING'|'REVIEW'|'EXPIRED';responsible:Role|'ALL';evidenceTypes?:string[];dueDays?:number|null};
type ReadinessRequirement={id:string;title:string;description:string;responsible:Role;sourceRuleId?:string;evidenceTypes?:string[];dueDays?:number|null;status:'REQUIRED'|'CONDITIONAL'};
type Profile={userId:string;headline:string;city:string;country:string;skills:string;bio:string;nationality?:string};
type Proof={id:string;userId:string;title:string;type:string;description:string;status:'PENDING'|'VERIFIED';createdAt:string};
type Doc={id:string;userId:string;name:string;type:string;status:'READY'|'MISSING';createdAt:string;expiresAt?:string};
type Client={id:string;ownerId:string;name:string;email:string;company:string;createdAt:string};
type Placement={id:string;agencyId:string;applicationId:string;candidate:string;jobTitle:string;status:'ACTIVE'|'COMPLETED'|'CANCELLED';createdAt:string};

