function normalizedJob(job:any):Job{
 return {...job,occupation:job.occupation||job.title,employmentModel:job.employmentModel||'Direct employment',internationalApplicants:job.internationalApplicants!==false,legalRuleIds:job.legalRuleIds||[]};
}
function rulesForJob(job:any,responsibility:Role):LegalRule[]{
 const j=normalizedJob(job);
 return legalRules.filter(r=>r.country===j.country && (r.audience==='ALL'||r.audience===responsibility));
}
function nationalityMatchesDestination(nationality:string,country:string){const n=nationality.trim().toLowerCase();const aliases:Record<string,string[]>={Germany:['germany','german','deutsch'],Poland:['poland','polish'],Georgia:['georgia','georgian']};return country==='EU / Cross-border'||(aliases[country]||[]).includes(n);}
function readinessRequirements(job:any,responsibility:Role,workerNationality=''):ReadinessRequirement[]{
 const j=normalizedJob(job); const rules=rulesForJob(j,responsibility); const crossBorder=!!workerNationality && !nationalityMatchesDestination(workerNationality,j.country);
 const req:ReadinessRequirement[]=[];
 rules.forEach(rule=>{
   if(responsibility==='WORKER'){
     if(rule.category==='Immigration'){
       req.push({id:`${j.id}-${rule.id}-passport`,title:'Identity / passport evidence',description:'Keep a current identity document available in the private Worker workspace.',responsible:'WORKER',sourceRuleId:rule.id,evidenceTypes:['Passport']});
       if(crossBorder||rule.status!=='REQUIRED') req.push({id:`${j.id}-${rule.id}-permit`,title:'Work authorisation evidence',description:'Add the applicable work permit or other work-authorisation evidence when required for this route.',responsible:'WORKER',sourceRuleId:rule.id,evidenceTypes:['Work permit']});
     } else if(rule.category==='Qualifications') req.push({id:`${j.id}-${rule.id}-qualification`,title:'Qualification / certificate evidence',description:'Keep relevant professional qualification evidence ready where the occupation requires it.',responsible:'WORKER',sourceRuleId:rule.id,evidenceTypes:['Certificate']});
     else req.push({id:`${j.id}-${rule.id}`,title:rule.title,description:'Review the official rule and confirm the requirement for this route.',responsible:'WORKER',sourceRuleId:rule.id});
   } else if(responsibility==='EMPLOYER'){
     if(rule.category==='Hiring foreign nationals'||rule.category==='Immigration') req.push({id:`${j.id}-${rule.id}-employer`,title:'Employer eligibility / authorisation check',description:'Confirm the employer-side process, sponsorship or work-authorisation duties that apply to this worker route.',responsible:'EMPLOYER',sourceRuleId:rule.id});
     else if(rule.category==='Employment') req.push({id:`${j.id}-${rule.id}-contract`,title:'Contract & employment compliance review',description:'Confirm contract terms, pay, working time, leave and applicable employment records before onboarding.',responsible:'EMPLOYER',sourceRuleId:rule.id});
     else req.push({id:`${j.id}-${rule.id}`,title:rule.title,description:'Review the official source and record the employer-side confirmation.',responsible:'EMPLOYER',sourceRuleId:rule.id});
   } else {
     if(rule.category==='Cross-border'||rule.category==='Posted workers') req.push({id:`${j.id}-${rule.id}-agency`,title:'Cross-border / placement check',description:'Confirm whether posting, labour-supply or placement obligations apply and record the official-source review.',responsible:'AGENCY',sourceRuleId:rule.id});
     else req.push({id:`${j.id}-${rule.id}`,title:rule.title,description:'Review the official source and record the agency-side confirmation for this placement.',responsible:'AGENCY',sourceRuleId:rule.id});
   }
 });
 return req;
}
function taskKey(requirementId:string,userId:string){return `${userId}:${requirementId}`}
function loadComplianceTasks():Record<string,{done:boolean;updatedAt:string}> {try{return JSON.parse(localStorage.getItem('workproof_compliance_tasks')||'{}')}catch{return {}}}
function saveComplianceTask(userId:string,requirementId:string,done:boolean){const all=loadComplianceTasks();all[taskKey(requirementId,userId)]={done,updatedAt:new Date().toISOString()};localStorage.setItem('workproof_compliance_tasks',JSON.stringify(all))}
function complianceForJob(job:any,workerId:string,responsibility:Role,workerNationality='',taskUserId=workerId):ComplianceCheck[]{
 const j=normalizedJob(job); const docs=workerId?readStore<Doc>('workproof_documents').filter(x=>x.userId===workerId):[]; const proof=workerId?readStore<Proof>('workproof_proof').filter(x=>x.userId===workerId):[]; const tasks=loadComplianceTasks(); const now=Date.now();
 return readinessRequirements(j,responsibility,workerNationality).map(req=>{
   let status:'READY'|'MISSING'|'REVIEW'|'EXPIRED'='REVIEW';
   if(req.evidenceTypes?.length){
     const evidence=req.evidenceTypes.some(t=>[...docs.map(d=>({type:d.type,status:d.status,expiresAt:d.expiresAt})),...proof.map(x=>({type:x.type,status:x.status}))].some((x:any)=>x.type===t&&x.status==='READY' || x.type===t&&x.status==='VERIFIED'));
     const expired=docs.some(d=>req.evidenceTypes!.includes(d.type)&&d.expiresAt&&new Date(d.expiresAt).getTime()<now);
     status=expired?'EXPIRED':evidence?'READY':'MISSING';
   } else if(tasks[taskKey(req.id,taskUserId)]) status=tasks[taskKey(req.id,taskUserId)].done?'READY':'REVIEW';
   else status='REVIEW';
   const rule=legalRules.find(r=>r.id===req.sourceRuleId)||legalRules.find(r=>r.country===j.country)||{id:req.id,country:j.country,audience:'ALL',category:'Workflow',title:req.title,summary:req.description,status:req.status==='REQUIRED'?'REQUIRED':'CONDITIONAL',source:'GoReadyTo workflow review',sourceUrl:'/legal',verifiedOn:'2026-09-17'} as LegalRule;
   return {id:req.id,rule,status,responsible:req.responsible,evidenceTypes:req.evidenceTypes,dueDays:req.dueDays};
 });
}
function overallCompliance(checks:ComplianceCheck[]):ComplianceStatus{
 if(!checks.length)return 'NOT_STARTED'; if(checks.some(c=>c.status==='EXPIRED'))return 'EXPIRED'; if(checks.some(c=>c.status==='MISSING'))return 'IN_PROGRESS'; if(checks.some(c=>c.status==='REVIEW'))return 'NEEDS_REVIEW'; return 'READY';
}
function ComplianceBadge({status}:{status:ComplianceStatus}){const label=status==='NEEDS_REVIEW'?'NEEDS REVIEW':status==='NOT_STARTED'?'NOT STARTED':status.replace('_',' ');return <span className={'compliance-badge '+status.toLowerCase()}>{label}</span>}
function CompliancePanel({job,workerId,responsibility,workerNationality,compact=false,taskUserId}:{job:Job;workerId:string;responsibility:Role;workerNationality?:string;compact?:boolean;taskUserId?:string}){
 const [,refresh]=useState(0); const ownerId=taskUserId||workerId; const checks=complianceForJob(job,workerId,responsibility,workerNationality,ownerId); const status=overallCompliance(checks); const done=checks.filter(c=>c.status==='READY').length; const toggle=(c:ComplianceCheck)=>{if(c.evidenceTypes?.length)return;saveComplianceTask(ownerId,c.id,c.status!=='READY');refresh(x=>x+1)};
 return <div className={compact?'compliance-panel compact':'compliance-panel'}><div className="compliance-head"><div><span className="eyebrow">READINESS ENGINE</span><h3>{workerNationality||'Worker nationality'} → {job.country}</h3><p>{job.occupation||job.title} · {job.employmentModel||'Direct employment'} · {done}/{checks.length||0} ready</p></div><ComplianceBadge status={status}/></div>{checks.length?<div className="compliance-list">{checks.map(c=><div className="compliance-row" key={c.id}><span className={'compliance-dot '+c.status.toLowerCase()}>{c.status==='READY'?<CheckCircle2 size={14}/>:c.status==='EXPIRED'?<AlertTriangle size={14}/>:c.status==='MISSING'?<AlertTriangle size={14}/>:<ClipboardCheck size={14}/>}</span><div><b>{c.rule.title}</b><small>{c.rule.category} · Responsible: {roleLabel(c.responsible as Role)}</small><p>{c.status==='READY'?'Ready — evidence or confirmation is recorded in the private workspace.':c.status==='EXPIRED'?'Expired — renew or replace the evidence before treating the route as ready.':c.status==='MISSING'?'Missing — add the required evidence to continue.':'Review — confirm this item against the official source.'}</p>{!c.evidenceTypes?.length&&<button className="mini-check" onClick={()=>toggle(c)}>{c.status==='READY'?'Mark for review':'Mark confirmed'}</button>}</div><a href={c.rule.sourceUrl} target="_blank" rel="noreferrer"><ExternalLink size={13}/></a></div>)}</div>:<div className="empty-inline"><Scale size={18}/><p>No verified rule set for this route yet.</p></div>}<small className="compliance-note">The engine tracks evidence and workflow confirmations; it does not decide legal eligibility.</small></div>
}

